import type React from 'react';
import './UniverseCard.css';

interface UniverseCardProps {
  id?: string;
  name: string;
  isCreateNew?: boolean;
  isFocused?: boolean;
  onClick: () => void;
  onKeyDown?: (e: React.KeyboardEvent) => void;
}

export const UniverseCard: React.FC<UniverseCardProps> = ({
  name,
  isCreateNew = false,
  isFocused = false,
  onClick,
  onKeyDown,
}) => {
  return (
    <div
      className={`universe-card ${isCreateNew ? 'universe-card--create' : ''} ${
        isFocused ? 'universe-card--focused' : ''
      }`}
      onClick={onClick}
      onKeyDown={onKeyDown}
      role="button"
      tabIndex={0}
      aria-label={isCreateNew ? 'Create new universe' : `Select ${name} universe`}
    >
      <div className="universe-card__content">
        {isCreateNew ? (
          <>
            <div className="universe-card__icon">+</div>
            <h3 className="universe-card__title">{name}</h3>
          </>
        ) : (
          <h3 className="universe-card__title">{name}</h3>
        )}
      </div>
    </div>
  );
};

import { Moon, Sun } from '@phosphor-icons/react';
import type React from 'react';
import { useEffect, useState } from 'react';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { useTheme } from '@/shared/hooks/useTheme';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { Universe } from '@/types/Universe';
import { CreateUniverseModal } from '../components/CreateUniverseModal';
import { UniverseCard } from '../components/UniverseCard';
import './UniverseSelection.css';

export const UniverseSelection: React.FC = () => {
  const [focusedIndex, setFocusedIndex] = useState<number>(0);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const { universes, isLoading, loadUniverses, createUniverse, setCurrentUniverse } =
    useUniverseStore();
  const navigate = useNavigationStore((state) => state.navigate);
  const { isDark, toggleTheme } = useTheme();

  // Theme toggle component (reused in all states)
  const ThemeToggle = () => (
    <button
      className="universe-selection__theme-toggle"
      onClick={toggleTheme}
      title={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
      aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
    >
      {isDark ? <Sun size={18} /> : <Moon size={18} />}
    </button>
  );

  // Load universes on mount
  useEffect(() => {
    loadUniverses();
  }, [loadUniverses]);

  const handleSelectUniverse = (universe: Universe) => {
    console.log('Selected universe:', universe);
    setCurrentUniverse(universe);
    // Navigate to stories list
    navigate({ screen: 'stories-list' });
  };

  const handleCreateUniverse = async (name: string) => {
    try {
      const input = {
        name,
        description: null,
        genre: null,
        tone: null,
        worldbuildingNotes: null,
        themes: null,
        color: null,
        icon: null,
        tags: null,
      };

      const newUniverse = await createUniverse(input);
      setIsModalOpen(false);

      // Select and navigate to the newly created universe
      handleSelectUniverse(newUniverse);
    } catch (error) {
      console.error('Failed to create universe:', error);
    }
  };

  const handleOpenCreateModal = () => {
    setIsModalOpen(true);
  };

  // Calculate total items (universes + "create new" card)
  const totalItems = universes.length + 1;

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't handle keyboard if modal is open
      if (isModalOpen) return;

      switch (e.key) {
        case 'ArrowRight':
          e.preventDefault();
          setFocusedIndex((prev) => (prev + 1) % totalItems);
          break;
        case 'ArrowLeft':
          e.preventDefault();
          setFocusedIndex((prev) => (prev - 1 + totalItems) % totalItems);
          break;
        case 'ArrowDown':
          e.preventDefault();
          // Move down in grid (assuming 3 columns)
          setFocusedIndex((prev) => {
            const newIndex = prev + 3;
            return newIndex < totalItems ? newIndex : prev;
          });
          break;
        case 'ArrowUp':
          e.preventDefault();
          // Move up in grid (assuming 3 columns)
          setFocusedIndex((prev) => {
            const newIndex = prev - 3;
            return newIndex >= 0 ? newIndex : prev;
          });
          break;
        case 'Enter':
          e.preventDefault();
          if (focusedIndex === universes.length) {
            // Last item is "Create New"
            handleOpenCreateModal();
          } else {
            // Select the focused universe
            handleSelectUniverse(universes[focusedIndex]);
          }
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [focusedIndex, totalItems, universes, isModalOpen]);

  if (isLoading) {
    return (
      <div className="universe-selection">
        <ThemeToggle />
        <div className="universe-selection__loading">
          <p>Loading universes...</p>
        </div>
      </div>
    );
  }

  // Empty state
  if (universes.length === 0) {
    return (
      <div className="universe-selection">
        <ThemeToggle />
        <div className="universe-selection__empty">
          <h1 className="universe-selection__title">Create your first universe</h1>
          <p className="universe-selection__subtitle">
            Start your creative journey by creating your first universe
          </p>
          <button className="btn btn-primary btn-lg" onClick={handleOpenCreateModal} autoFocus>
            Create Universe
          </button>
        </div>

        <CreateUniverseModal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          onSubmit={handleCreateUniverse}
        />
      </div>
    );
  }

  // Populated state
  return (
    <div className="universe-selection">
      <ThemeToggle />
      <div className="universe-selection__container">
        <h1 className="universe-selection__header">Select a Universe</h1>

        <div className="universe-grid">
          {universes.map((universe, index) => (
            <UniverseCard
              key={universe.id}
              id={universe.id}
              name={universe.name}
              isFocused={focusedIndex === index}
              onClick={() => handleSelectUniverse(universe)}
            />
          ))}

          <UniverseCard
            name="Create New Universe"
            isCreateNew
            isFocused={focusedIndex === universes.length}
            onClick={handleOpenCreateModal}
          />
        </div>
      </div>

      <CreateUniverseModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleCreateUniverse}
      />
    </div>
  );
};

/**
 * Settings View
 *
 * Application settings and preferences management.
 * Focused single-purpose view for managing app configuration.
 */

import { ArrowCounterClockwise, ArrowLeft } from '@phosphor-icons/react';
import {
  type SnapshotTrigger,
  useSettingsStore,
} from '@/features/settings/stores/useSettingsStore';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import { useToastStore } from '@/shared/stores/useToastStore';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';
import './Settings.css';

// Preset character threshold options
const THRESHOLD_PRESETS = [
  { label: '250 characters', value: 250 },
  { label: '500 characters', value: 500 },
  { label: '1,000 characters', value: 1000 },
  { label: '2,000 characters', value: 2000 },
];

// Preset max snapshots options
const MAX_SNAPSHOTS_PRESETS = [
  { label: '25 snapshots', value: 25 },
  { label: '50 snapshots', value: 50 },
  { label: '100 snapshots', value: 100 },
  { label: '200 snapshots', value: 200 },
];

export function Settings() {
  const goBack = useNavigationStore((state) => state.goBack);
  const canGoBack = useNavigationStore((state) => state.canGoBack);
  const navigate = useNavigationStore((state) => state.navigate);
  const showSuccess = useToastStore((state) => state.success);

  const {
    snapshotTrigger,
    snapshotCharacterThreshold,
    maxSnapshotsPerVersion,
    setSnapshotTrigger,
    setSnapshotCharacterThreshold,
    setMaxSnapshotsPerVersion,
    resetToDefaults,
  } = useSettingsStore();

  const handleBack = () => {
    if (canGoBack()) {
      goBack();
    } else {
      // Fallback to stories list if no history
      navigate({ screen: 'stories-list' });
    }
  };

  const handleTriggerChange = (trigger: SnapshotTrigger) => {
    setSnapshotTrigger(trigger);
    showSuccess(
      trigger === 'on_leave'
        ? 'Snapshots: when leaving editor'
        : 'Snapshots: based on character count',
    );
  };

  const handleThresholdChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const newThreshold = parseInt(event.target.value, 10);
    setSnapshotCharacterThreshold(newThreshold);
    showSuccess(`Snapshot threshold set to ${newThreshold.toLocaleString()} characters`);
  };

  const handleMaxSnapshotsChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const newMax = parseInt(event.target.value, 10);
    setMaxSnapshotsPerVersion(newMax);
    showSuccess(`Max snapshots set to ${newMax}`);
  };

  const handleResetToDefaults = () => {
    resetToDefaults();
    showSuccess('Settings reset to defaults');
  };

  return (
    <div className="settings">
      {/* Header */}
      <div className="settings-header">
        <button className="back-button" onClick={handleBack} aria-label="Go back" title="Back">
          <ArrowLeft size={20} />
        </button>

        <div className="header-content">
          <h1 className="page-title">Settings</h1>
          <p className="page-subtitle">Manage your application preferences</p>
        </div>
      </div>

      {/* Settings Content */}
      <div className="settings-content">
        <div className="settings-section">
          <h2 className="section-title">Auto-Save Snapshots</h2>
          <p className="section-description">
            Configure automatic snapshot creation to track your writing progress
          </p>

          {/* Snapshot Trigger Mode */}
          <div className="setting-item">
            <div className="setting-info">
              <label className="setting-label">Snapshot trigger</label>
              <p className="setting-description">Choose when to create automatic snapshots</p>
            </div>
            <div className="setting-control">
              <div className="radio-group">
                <label className="radio-option">
                  <input
                    type="radio"
                    name="snapshot-trigger"
                    value="on_leave"
                    checked={snapshotTrigger === 'on_leave'}
                    onChange={() => handleTriggerChange('on_leave')}
                  />
                  <span className="radio-label">When leaving editor</span>
                </label>
                <label className="radio-option">
                  <input
                    type="radio"
                    name="snapshot-trigger"
                    value="character_count"
                    checked={snapshotTrigger === 'character_count'}
                    onChange={() => handleTriggerChange('character_count')}
                  />
                  <span className="radio-label">Based on character count</span>
                </label>
              </div>
            </div>
          </div>

          {/* Character Threshold (only visible when trigger is 'character_count') */}
          {snapshotTrigger === 'character_count' && (
            <div className="setting-item">
              <div className="setting-info">
                <label htmlFor="snapshot-threshold" className="setting-label">
                  Character threshold
                </label>
                <p className="setting-description">
                  Create a snapshot after typing this many characters
                </p>
              </div>
              <div className="setting-control">
                <select
                  id="snapshot-threshold"
                  className="input-filled delay-select"
                  value={snapshotCharacterThreshold}
                  onChange={handleThresholdChange}
                >
                  {THRESHOLD_PRESETS.map((preset) => (
                    <option key={preset.value} value={preset.value}>
                      {preset.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          )}

          {/* Max Snapshots per Version */}
          <div className="setting-item">
            <div className="setting-info">
              <label htmlFor="max-snapshots" className="setting-label">
                Maximum snapshots per version
              </label>
              <p className="setting-description">
                Oldest snapshots are removed when this limit is reached
              </p>
            </div>
            <div className="setting-control">
              <select
                id="max-snapshots"
                className="input-filled delay-select"
                value={maxSnapshotsPerVersion}
                onChange={handleMaxSnapshotsChange}
              >
                {MAX_SNAPSHOTS_PRESETS.map((preset) => (
                  <option key={preset.value} value={preset.value}>
                    {preset.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="settings-actions">
          <button
            className="btn btn-outline btn-base"
            onClick={handleResetToDefaults}
            title="Reset all settings to default values"
          >
            <ArrowCounterClockwise size={18} weight="duotone" />
            Reset to Defaults
          </button>
        </div>
      </div>
    </div>
  );
}

