@import "../../../design-system/tokens/colors/modern-indigo.css";
@import "../../../design-system/tokens/typography/classic-serif.css";
@import "../../../design-system/tokens/spacing.css";

.universe-card {
  /* Size */
  width: 240px;
  height: 180px;

  /* Rounded square */
  border-radius: 12px;

  /* Elevated shadow (from design system) */
  background: var(--color-surface);
  box-shadow: var(--shadow-base);

  /* Cursor */
  cursor: pointer;

  /* Transition for hover and focus */
  transition: all 0.2s ease;

  /* Remove button default styles */
  border: 2px solid transparent;
  outline: none;

  /* Content positioning */
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-6);
}

.universe-card__content {
  text-align: center;
  width: 100%;
}

.universe-card__title {
  font-family: var(--typography-heading-font);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  margin: 0;
  line-height: 1.3;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* Hover effect - slight lift */
.universe-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

/* Focus state - visible border for keyboard navigation */
.universe-card--focused {
  border-color: var(--color-primary);
  box-shadow:
    var(--shadow-lg),
    0 0 0 3px var(--color-primary-subtle);
}

/* Active/pressed state */
.universe-card:active {
  transform: translateY(-2px);
}

/* Create new card variant */
.universe-card--create {
  border: 2px dashed var(--color-border);
  background: var(--color-surface-secondary);
}

.universe-card--create:hover {
  border-color: var(--color-primary);
  background: var(--color-surface);
}

.universe-card--create.universe-card--focused {
  border-color: var(--color-primary);
  border-style: solid;
}

.universe-card__icon {
  font-size: var(--typography-h1-size);
  font-weight: var(--font-weight-normal);
  color: var(--color-primary);
  margin-bottom: var(--spacing-2);
  line-height: 1;
}

/* Light mode - add border for definition */
:root[data-theme="light"] .universe-card,
html[data-theme="light"] .universe-card {
  border: 1px solid var(--color-border);
}

import type React from 'react';
import { useEffect, useRef, useState } from 'react';
import './CreateUniverseModal.css';

interface CreateUniverseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (name: string) => void;
}

export const CreateUniverseModal: React.FC<CreateUniverseModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  // Focus input when modal opens
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [isOpen, onClose]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    if (!name.trim()) {
      setError('Universe name is required');
      return;
    }

    if (name.trim().length < 2) {
      setError('Universe name must be at least 2 characters');
      return;
    }

    // Submit
    onSubmit(name.trim());
    setName('');
    setError('');
  };

  const handleClose = () => {
    setName('');
    setError('');
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={handleClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2 className="modal-title">Create New Universe</h2>
          <button className="modal-close" onClick={handleClose} aria-label="Close modal">
            ×
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="universe-name" className="form-label">
              Universe Name
            </label>
            <input
              ref={inputRef}
              id="universe-name"
              type="text"
              className={`form-input ${error ? 'form-input--error' : ''}`}
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                setError('');
              }}
              placeholder="Enter universe name"
              aria-invalid={!!error}
              aria-describedby={error ? 'name-error' : undefined}
            />
            {error && (
              <p id="name-error" className="form-error">
                {error}
              </p>
            )}
          </div>

          <div className="modal-actions">
            <button type="button" className="btn btn-secondary btn-base" onClick={handleClose}>
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base">
              Create Universe
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

